def solve_graceful_labeling_pysat():
    # Number of vertices: 16
    # Number of edges: 36
    # Labels: 0 to 36

    # Variables: x[v][l] is true if vertex v has label l
    # v in 0..15, l in 0..36
    # Total variables: 16 * 37 = 592

    def get_var(v, l):
        return v * 37 + l + 1

    solver = Glucose3()

    # Each vertex has exactly one label
    for v in range(16):
        solver.add_clause([get_var(v, l) for l in range(37)])
        for l1 in range(37):
            for l2 in range(l1 + 1, 37):
                solver.add_clause([-get_var(v, l1), -get_var(v, l2)])

    # Each label is used at most once
    for l in range(37):
        for v1 in range(16):
            for v2 in range(v1 + 1, 16):
                solver.add_clause([-get_var(v1, l), -get_var(v2, l)])

    # Edges
    edges = []
    for k in range(4):
        for i in range(4):
            for j in range(i + 1, 4):
                edges.append((4*k + i, 4*k + j))
    for k in range(3):
        for i in range(4):
            edges.append((4*k + i, 4*(k+1) + i))

    # Edge labels: e[edge_idx][diff] is true if edge_idx has label diff
    # edge_idx in 0..35, diff in 1..36
    # Total variables: 36 * 36 = 1296
    # Total variables so far: 592 + 1296 = 1888

    def get_edge_var(e_idx, diff):
        return 16 * 37 + e_idx * 36 + diff

    # Each edge has exactly one label
    for e_idx in range(36):
        solver.add_clause([get_edge_var(e_idx, diff) for diff in range(1, 37)])
        for d1 in range(1, 37):
            for d2 in range(d1 + 1, 37):
                solver.add_clause([-get_edge_var(e_idx, d1), -get_edge_var(e_idx, d2)])

    # Each edge label is used at most once
    for diff in range(1, 37):
        for e1 in range(36):
            for e2 in range(e1 + 1, 36):
                solver.add_clause([-get_edge_var(e1, diff), -get_edge_var(e2, diff)])

    # Edge label constraint: |label(u) - label(v)| = diff
    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(37):
            for l2 in range(37):
                diff = abs(l1 - l2)
                if diff >= 1:
                    # If vertex u has label l1 and vertex v has label l2, then edge e_idx has label diff
                    solver.add_clause([-get_var(u, l1), -get_var(v, l2), get_edge_var(e_idx, diff)])
                    # Also need the reverse: if edge e_idx has label diff, then (u,v) must have labels (l1, l2) such that |l1-l2|=diff
                    # This is implicitly handled by the "each edge has exactly one label" and "each vertex has exactly one label"
                    # But let's add it for completeness if needed. Actually, the above is enough.

    if solver.solve():
        model = solver.get_model()
        labels = [0] * 16
        for v in range(16):
            for l in range(37):
                if model[get_var(v, l) - 1] > 0:
                    labels[v] = l
                    break
        return labels
    else:
        return None

